const state={catalog:null,cart:new Map(),coupon:'',quote:null,affiliate:'',order:null,token:'',tab:'today',admin:null,goaffproPreview:null,affiliateProfile:null,profileSlug:'',profileToken:'',customer:null,customerAdmin:null,points:0,migrationPreview:null,setupId:'',setupToken:'',orderSearch:'',orderStatus:'all',orderMode:'all',shoppingView:'store',canOrderForCustomer:false,orderForCustomer:false,editingOrderId:'',checkoutValues:{}};
let toastTimer;
function toast(s,opts){const t=document.querySelector('#toast');t.textContent=s;if(opts&&opts.bag){const b=document.createElement('button');b.type='button';b.className='toast-action';b.dataset.action='view-bag';b.textContent='View bag';t.append(' ',b)}t.style.display='block';t.classList.remove('show');void t.offsetWidth;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>{t.classList.remove('show');t.style.display='none'},opts&&opts.bag?4000:5000)}
async function api(path,data,token){const opts={headers:{}};if(data!==undefined){opts.method='POST';opts.headers['Content-Type']='application/json';opts.body=JSON.stringify(data)}if(token)opts.headers['X-Order-Token']=token;opts.headers['X-Store-Request']='1';const r=await fetch('/api'+path.replace(/^\/api/,''),opts);const result=await r.json();if(!r.ok)throw new Error(result.error||'Request failed');return result}
function productOrderLimit(p){return Number.isInteger(p.max_order_quantity)&&p.max_order_quantity>0?p.max_order_quantity:100}
function productGroupQuantity(p){if(!p.purchase_limit_group)return 0;return Array.from(state.cart).reduce((n,[id,qty])=>n+(state.catalog.products.find(x=>x.id===id)?.purchase_limit_group===p.purchase_limit_group?qty:0),0)}
function productCanAdd(p){return (state.cart.get(p.id)||0)<productOrderLimit(p)&&(!p.purchase_limit_group||productGroupQuantity(p)<p.max_group_quantity)}
function trimSavedCartLimits(){const groups=new Map();for(const [id,qty] of state.cart){const p=state.catalog.products.find(x=>x.id===id);if(!p?.purchase_limit_group)continue;const used=groups.get(p.purchase_limit_group)||0,allowed=Math.max(0,Math.min(qty,p.max_group_quantity-used));if(allowed)state.cart.set(id,allowed);else state.cart.delete(id);groups.set(p.purchase_limit_group,used+allowed);if(allowed<qty)toast('Limit 3 sale vials total per order. Mix and match.')}}
const button=(label,action,cls='')=>`<button type="button" data-action="${action}" class="${cls}">${label}</button>`;
function couponCodeList(value=state.coupon){return [...new Set(String(value||'').split(',').map(c=>c.trim().toUpperCase()).filter(Boolean))]}
function friendCode(){try{const f=new URLSearchParams(location.search||'').get('friend');if(f&&/^[0-9a-f]{10}$/i.test(f))localStorage.setItem('glow_friend',f.toLowerCase());return localStorage.getItem('glow_friend')||''}catch{return ''}}friendCode();
function doubleUntil(st){const t=Date.now()/1000,w=((st&&st.double_points&&st.double_points.windows)||[]).find(w=>t>=w.from&&t<w.until);return w?w.until:0}
function untilText(ts){return new Date(ts*1000).toLocaleString('en-US',{timeZone:'America/New_York',weekday:'short',hour:'numeric',minute:'2-digit'})+' ET'}
