function cartData(){const codes=couponCodeList();return{items:Array.from(state.cart,([id,quantity])=>({id,quantity})),coupon:codes[0]||'',coupons:codes,affiliate:state.affiliate,points_redeemed:state.points,order_for_customer:state.orderForCustomer,friend:(()=>{try{return localStorage.getItem('glow_friend')||''}catch{return ''}})()}}
async function calculateForCart(){const notes=[];for(let i=0;i<8;i++){try{await calculate();return notes}catch(err){const m=String(err&&err.message||'');if(BR().id==='zader'&&/Affiliates cannot earn commission on their own purchases/.test(m)){clearNativeReferral();notes.push('Your own affiliate referral and coupon codes were removed. Your personal order will not earn affiliate commission.');continue}if(state.coupon&&(/These coupon codes cannot be used together|Coupons from different affiliates cannot be combined|Use no more than two coupon codes per order/.test(m))){notes.push('The saved coupon combination is no longer available, so those codes were removed. Your products are still in your bag.');state.coupon='';continue}if(state.coupon&&(m==='Coupon is unavailable or expired.'||m==='Cart does not meet the coupon minimum.')){notes.push('The code '+state.coupon+' is not active right now, so it was taken off. Everything else is in your bag.');state.coupon='';continue}if(state.affiliate&&m==='Affiliate storefront is unavailable.'){state.affiliate='';state.affiliateProfile=null;try{sessionStorage.removeItem('glow_customer_store')}catch{}continue}if(state.points&&/points/i.test(m)){state.points=0;notes.push('Your rewards points were taken off this order. You can add them again in your bag.');continue}const low=m.match(/^Only (\d+) of (.+) available\.$/);if(low&&!state.editingOrderId){const n=Number(low[1]),hit=[...state.cart].find(([pid])=>{const p=state.catalog.products.find(x=>x.id===pid);return p&&p.name===low[2]});if(hit){const q=Math.min(hit[1]-1,n);if(q<=0){state.cart.delete(hit[0]);notes.push(low[2]+' just sold out, so it was taken out of your bag.')}else{state.cart.set(hit[0],q);notes.push('We don’t have that many of '+low[2]+' right now, so your bag now has '+q+'.')}continue}}if((m==='A product is unavailable.'||low)&&!state.editingOrderId){const fresh=await api('/api/catalog');state.catalog=fresh;let changed=false;for(const[pid,q]of [...state.cart]){const p=fresh.products.find(x=>x.id===pid);if(!p||!(p.stock>0)){state.cart.delete(pid);changed=true;notes.push((p?p.name:'One item')+' just sold out, so it was taken out of your bag.')}else if(q>p.stock){state.cart.set(pid,p.stock);changed=true}}if(changed)continue}throw err}}throw new Error('Please refresh the page and try again.')}
async function calculate(){state.quote=state.cart.size?await api(state.editingOrderId?'/api/orders/'+state.editingOrderId+'/edit-quote':'/api/quote',cartData(),state.editingOrderId?state.token:undefined):null;sessionStorage.setItem('glow_cart',JSON.stringify(cartData()));if(state.cart.size)track('bag');syncBag()}
function totals(q){const codes=Array.isArray(q.coupons)?q.coupons:q.coupon?[q.coupon]:[];return `${codes.length?`<p class="muted">Applied coupons: ${codes.map(esc).join(', ')}</p>`:''}<div class="row"><span>Subtotal</span><span>${money(q.subtotal)}</span></div>${(q.coupon_discount??(q.discount-(q.subscription_discount||0)))?`<div class="row discount-row"><span>Promo discount</span><span>−${money(q.coupon_discount??(q.discount-(q.subscription_discount||0)))}</span></div>`:''}${q.subscription_discount?`<div class="row discount-row"><span>Subscribe &amp; save</span><span>−${money(q.subscription_discount)}</span></div>`:''}${q.member_discount?`<div class="row discount-row sk-row"><span>Skool member ${esc(q.member?.pct||'')}% off</span><span>−${money(q.member_discount)}</span></div>`:''}${q.rewards_discount?`<div class="row"><span>Rewards (${q.points_redeemed} points)</span><span>−${money(q.rewards_discount)}</span></div>`:''}${q.member?.free_shipping&&q.member.shipping_waived?`<div class="row discount-row sk-row"><span>Shipping · free with your Skool membership</span><span><s class="muted">${money(q.member.shipping_waived)}</s> ${money(q.shipping)}</span></div>`:`<div class="row"><span>Shipping</span><span>${money(q.shipping)}</span></div>`}${q.tax?`<div class="row"><span>Tax</span><span>${money(q.tax)}</span></div>`:''}${q.coupon&&q.coupon_excluded_subtotal>0?`<p class="muted">${q.coupon_eligible_subtotal>0?'Promo code applied to eligible products only. Special-price items are excluded.':'These products are excluded from promo codes. No promo discount was applied.'}</p>`:''}<div class="row total"><span>Total</span><span>${money(q.total)}</span></div>${q.member_note?`<p class="muted sk-note">${esc(q.member_note)}</p>`:''}${q===state.quote&&typeof skShipHint==='function'?skShipHint(q):''}${q.affiliate_name?`<p class="muted">Affiliate credit: ${esc(q.affiliate_name)}${q.affiliate_source==='coupon'?' (coupon code)':''}</p>`:''}`}
async function loadStore(){try{state.canOrderForCustomer=(await api('/api/admin/checkout-context')).can_order_for_customer===true}catch{state.canOrderForCustomer=false}state.orderForCustomer=false;const incomingCoupon=new URLSearchParams(location.search||'').get('coupon');if(incomingCoupon&&incomingCoupon.length<=40)state.coupon=incomingCoupon.trim();state.affiliate='';state.affiliateProfile=null;const emailed=location.hash?.match(/^#order=((?:GLP|ZDR|PEP)-[A-F0-9]{10})\.([A-Za-z0-9_-]{43}|r_\d{10}_[A-Za-z0-9_-]{43})$/);if(emailed){history.replaceState(null,'',location.pathname);sessionStorage.setItem('glow_order',JSON.stringify({id:emailed[1],token:emailed[2]}))}state.catalog=await api('/api/catalog');nativeRestoreReferral();renderMode(state.catalog.settings);try{state.customer=await api('/api/account')}catch{state.customer=null}const rawSlug=isMerchPage()?'':decodeURIComponent(location.pathname.replace(/^\/store-next\/?/,'').replace(/\/$/,''));let slug=rawSlug.toLowerCase();if(slug){try{state.affiliateProfile=await api('/api/storefronts/'+encodeURIComponent(slug)).catch(()=>api('/api/referrals/'+encodeURIComponent(rawSlug)));state.affiliate=state.affiliateProfile.slug;slug=state.affiliate;if(location.pathname!=='/store-next/'+slug)history.replaceState(null,'','/store-next/'+slug+(location.search||''));sessionStorage.setItem('glow_customer_store',state.affiliate);document.title=state.affiliateProfile.name+' · '+(BR().id==='zader'?'Zader Health':'Glow Store');document.querySelectorAll('header a[href="/store-next/"]').forEach(a=>a.setAttribute('href','/store-next/'+slug))}catch{history.replaceState(null,'','/store-next/'+(location.search||''));slug=''}}if(!slug){const ref=new URLSearchParams(location.search||'').get('ref')||sessionStorage.getItem('glow_referral');const savedAffiliate=sessionStorage.getItem('glow_customer_store');if(ref||savedAffiliate){try{state.affiliateProfile=await api(ref?'/api/referrals/'+encodeURIComponent(ref):'/api/storefronts/'+encodeURIComponent(savedAffiliate));state.affiliate=state.affiliateProfile.slug;sessionStorage.setItem('glow_customer_store',state.affiliate);document.title=state.affiliateProfile.name+' · '+(BR().id==='zader'?'Zader Health':'Glow Store')}catch{sessionStorage.removeItem('glow_referral');sessionStorage.removeItem('glow_customer_store');toast('This affiliate link is unavailable. You can still shop in the main store.')}}}else{sessionStorage.removeItem('glow_referral')}nativeRememberReferral();const savedCart=sessionStorage.getItem('glow_cart');if(savedCart){try{const c=JSON.parse(savedCart);state.cart=new Map(c.items.filter(i=>Number.isInteger(i.id)&&Number.isInteger(i.quantity)&&i.quantity>0&&i.quantity<=100&&state.catalog.products.some(p=>p.id===i.id&&p.stock>=i.quantity)).map(i=>[i.id,Math.min(i.quantity,productOrderLimit(state.catalog.products.find(p=>p.id===i.id)))]));state.coupon=incomingCoupon&&incomingCoupon.length<=40?incomingCoupon.trim():Array.isArray(c.coupons)?c.coupons.join(','):typeof c.coupon==='string'?c.coupon:'';trimSavedCartLimits();await calculateForCart()}catch{state.cart.clear();state.coupon='';state.quote=null;sessionStorage.removeItem('glow_cart')}}const saved=sessionStorage.getItem('glow_order');state.savedCheckout=null;if(saved){try{const d=JSON.parse(saved);if(!d.id||!d.token)throw new Error('Invalid saved checkout');state.savedCheckout=d;if(emailed){state.order=await api('/api/orders/'+d.id,undefined,d.token);state.token=d.token;renderOrder();return}}catch{sessionStorage.removeItem('glow_order');state.savedCheckout=null}}renderStore();if(await growthOnLoad())return;if(/^#bag$/.test(location.hash||'')&&state.cart.size){subStoreReturn();await calculate().catch(()=>{});renderBag();scrollTo({top:0,behavior:'instant'})}else if(/^#(collection|catalog|products?|shop)$/i.test(location.hash||''))requestAnimationFrame(()=>{const c=document.getElementById('collection');if(c)c.scrollIntoView({block:'start'})})}

function focusLegacyProduct(){const m=location.hash?.match(/^#product\/([a-z0-9-]+)$/);if(!m)return;const ids=new Set(state.catalog.products.filter(p=>p.slug===m[1]).map(p=>String(p.id)));if(!ids.size)return;document.querySelectorAll('#products .card').forEach(c=>c.hidden=!ids.has(c.dataset.productId));updateProductGroups()}
function updateBagButton(){const b=document.querySelector('[data-action="view-bag"]');if(!b)return;const count=Array.from(state.cart.values()).reduce((n,q)=>n+q,0);b.hidden=false;b.textContent='View bag ('+count+')';b.classList.toggle('has-items',count>0)}
function octoberSaleBanner(now=Date.now()){
 if(BR().id!=='glow'||now<Date.parse('2026-10-31T00:00:00-04:00')||now>=Date.parse('2026-11-01T00:00:00-04:00'))return '';
 const offer=new URL(location.href);offer.searchParams.set('coupon','scarecrow');offer.hash=isMerchPage()?'':'collection';
 return `<section class="poe-october-sale poe-flash-sale" aria-label="October 31 flash sale"><div class="poe-sale-copy"><p class="poe-sale-eyebrow">October 31 · Today only</p><h2>Flash Sale</h2><p class="poe-flash-price">$13 <span>each</span></p><ul class="poe-flash-products"><li>Selank 5mg</li><li>Semax 5mg</li><li>GHK-Cu 100mg</li></ul><p class="poe-flash-discount">Plus 30% off regular-priced items</p><p class="poe-sale-code">Use code <code>scarecrow</code></p><a class="poe-sale-link" href="${esc(offer.pathname+offer.search+offer.hash)}">Shop the flash sale <span aria-hidden="true">→</span></a><p class="poe-sale-terms">Limit 3 sale vials total per order. Mix and match.</p><p class="poe-sale-terms">Ends October 31 at 11:59 PM Eastern · While supplies last</p></div></section>`;
}
// Veterans Day subscription gifts (Jonah, 10 Nov 2026). Shown only on 11 Nov 2026 (Eastern) while Subscribe & save is open.
const VD={start:Date.parse('2026-11-11T00:00:00-05:00'),end:Date.parse('2026-11-12T00:00:00-05:00'),trz:11,mito:28,aicar:24,cap:40000};
const vdUsd=c=>'$'+Math.round((c||0)/100).toLocaleString('en-US');
function vdOpen(now=Date.now()){return BR().id==='glow'&&now>=VD.start&&now<VD.end&&!!state.catalog?.settings?.subscribe_open}
function vdName(id,fallback){const p=(state.catalog?.products||[]).find(x=>x.id===id);return p?String(p.name).replace(/\s*·\s*/g,' '):fallback}
// Each tier's own gifts; the tier cards list everything in that box, lower tiers included (Jonah, 11 Nov 2026).
function vdGiftsByTier(){return [['1× '+vdName(VD.trz,'GLP-2T 20 mg')],['2× '+vdName(VD.mito,'Mito-31'),'1× Glow tote you pick'],['1× '+vdName(VD.aicar,'AICAR 50 mg')],['1× Kit of 10 you choose (up to '+vdUsd(VD.cap)+')']]}
function vdLadder(){const own=vdGiftsByTier();return ['$125+','$250+','$400+','$600+'].map((m,i)=>[m,own.slice(0,i+1).flat()])}
// Flags falling like snow (Jonah, 11 Nov 2026): "it has to be indefinite and can't look like it repeats". Every flag is
// born with its own random size, speed, drift, sway and flutter, and is replaced by a new random one when it lands, so
// the pattern never loops. Decorative only: hidden from screen readers, no clicks, off for reduced motion.
const VD_FLAG='<svg viewBox="0 0 19 13"><use href="#vd-flag"/></svg>';
function vdSnow(){return `<div class="vd-snow vd-snow-page" aria-hidden="true"><svg width="0" height="0" style="position:absolute"><defs><symbol id="vd-flag" viewBox="0 0 19 13"><rect width="19" height="13" fill="#fff"/>${[0,2,4,6,8,10,12].map(y=>`<rect y="${y}" width="19" height="1" fill="#b22234"/>`).join('')}<rect width="7.6" height="7" fill="#3c3b6e"/>${[[1.3,1.2],[3.8,1.2],[6.3,1.2],[2.55,2.9],[5.05,2.9],[1.3,4.6],[3.8,4.6],[6.3,4.6]].map(([x,y])=>`<circle cx="${x}" cy="${y}" r=".45" fill="#fff"/>`).join('')}</symbol></defs></svg></div>`}
function vdDrop(box,midway){
 if(!box.isConnected)return;const R=Math.random,depth=R(),size=10+depth*14,h=box.clientHeight+70,el=document.createElement('span');
 el.style.cssText=`left:${(R()*104-2).toFixed(2)}%;--s:${size.toFixed(1)}px;opacity:${(.45+depth*.45).toFixed(2)}`;
 el.innerHTML='<i>'+VD_FLAG+'</i>';box.appendChild(el);const sway=el.firstChild,flag=sway.firstChild;
 // Three layers, each with its own random timing, so the motion is smooth and never lines up the same way twice:
 // the fall (steady, closer flags faster), a soft side-to-side sway, and a gentle flutter.
 const dur=(15-depth*6+R()*5)*1000*Math.max(.7,h/600),drift=(R()-.5)*70;
 const fall=el.animate([{transform:'translate3d(0,-50px,0)'},{transform:`translate3d(${drift.toFixed(1)}px,${h}px,0)`}],{duration:dur,easing:'linear',fill:'forwards'});
 const amp=10+R()*28,tilt=8+R()*16;
 sway.animate([{transform:`translate3d(${-amp}px,0,0) rotate(${-tilt}deg)`},{transform:`translate3d(${amp}px,0,0) rotate(${tilt}deg)`}],{duration:2200+R()*2600,delay:-R()*4000,direction:'alternate',iterations:Infinity,easing:'cubic-bezier(.45,0,.55,1)'});
 const sk=(R()*10-5).toFixed(1);flag.animate([{transform:`scaleX(${(.35+R()*.25).toFixed(2)}) skewY(${sk}deg)`},{transform:`scaleX(1) skewY(${-sk}deg)`}],{duration:900+R()*1600,delay:-R()*2000,direction:'alternate',iterations:Infinity,easing:'cubic-bezier(.45,0,.55,1)'});
 if(midway)fall.currentTime=R()*dur*.95;
 fall.onfinish=()=>{el.remove();setTimeout(()=>vdDrop(box,false),R()*1600)}}
// Flags over the whole store page (Jonah: "the flags on the whole page" ... "it can't hover over the products, only
// behind it"): one fixed layer BEHIND everything (z-index -1, body made see-through so the page's white shows from
// the root), so cards, photos and text always sit on top. The banner has its own layer behind its words. Only while
// the Veterans Day offer shows, only on customer pages (never Management, Packing or Live); it removes itself after.
function vdSnowStart(){if(typeof document==='undefined'||!document.querySelector||!document.body)return;
 const page=document.querySelector('.vd-snow-page'),want=typeof vdOpen==='function'&&vdOpen()&&!/\/(admin|packing|live|staff)/.test(location.pathname);
 if(!want){if(page){page.remove();document.body.classList.remove('vd-snowing')}return}
 let reduce=false;try{reduce=matchMedia('(prefers-reduced-motion: reduce)').matches}catch{}if(reduce||typeof Element==='undefined'||!Element.prototype.animate)return;
 if(!page){const box=document.createElement('div');box.innerHTML=vdSnow();const el=box.firstElementChild;document.body.appendChild(el);document.body.classList.add('vd-snowing');el.dataset.on='1';const n=innerWidth<600?16:32;for(let i=0;i<n;i++)vdDrop(el,true)}
 for(const b of document.querySelectorAll('.vd-sale .vd-snow:not([data-on])')){b.dataset.on='1';const n=b.clientWidth<600?8:16;for(let i=0;i<n;i++)vdDrop(b,true)}}
try{if(typeof setInterval==='function'&&typeof document!=='undefined')setInterval(vdSnowStart,700)}catch{}
function veteransBanner(){if(!vdOpen())return '';return `<section class="vd-sale" aria-label="Veterans Day subscription gifts"><div class="vd-snow" aria-hidden="true"></div><div class="vd-stars" aria-hidden="true">★ ★ ★</div><p class="vd-eyebrow">Veterans Day · Today only · Subscriptions only</p><h2>Subscribe today.<br>Unlock free gifts.</h2><p class="vd-lead">Start any Subscribe &amp; save subscription today and your first box unlocks free gifts. <strong>They stack</strong>: reach Tier 4 and you get all four.</p><ol class="vd-ladder">${vdLadder().map(([m,g],i)=>`<li><span class="vd-min">Tier ${i+1}</span><span class="vd-at">First box ${m}</span><span class="vd-inbox">Free in your box</span><ul class="vd-gifts">${g.map((x,k)=>`<li class="${k>=g.length-vdGiftsByTier()[i].length?'new':''}">${esc(x)}</li>`).join('')}</ul></li>`).join('')}</ol><a class="vd-cta" href="#collection">Build your box <span aria-hidden="true">→</span></a><p class="vd-terms">Based on your first box after the 15% off, before shipping. New subscriptions only. Gifts ship free in your first box. Ends 11:59 PM Eastern tonight. While supplies last. For research use only.</p></section>`}
