function vdBoxText(t,v){const i=v.tiers.indexOf(t),out=[];for(const x of v.tiers.slice(0,i+1)){for(const g of x.gifts)out.push((g.quantity>1?g.quantity+'× ':'')+g.name+(g.in_stock?'':' (sold out)'));if(x.bag)out.push('Glow tote (your pick)');if(x.kit)out.push('Kit of 10 you choose (up to '+vdUsd(v.kit_cap_cents)+')')}return 'Free: '+out.join(' · ')}
function vdGiftText(t,v){if(t.kit)return 'Your own Kit of 10, free (up to '+vdUsd(v.kit_cap_cents)+')';const g=t.gifts.map(x=>(x.quantity>1?x.quantity+' free ':'Free ')+x.name+(x.in_stock?'':' (sold out)')).join(' + ');return t.bag?g+' + a Glow tote you pick':g}
function vdNeedChoice(v){if(!v)return '';const won=v.tiers.filter(t=>t.unlocked);if(won.some(t=>t.bag)&&(v.totes||[]).length&&!(v.totes||[]).some(x=>String(x.id)===String(state.vdBag)))return 'bag';if(won.some(t=>t.kit)&&!v.kits.some(k=>k.id===state.vdKit))return 'kit';return ''}
function vdPanel(q){const v=q.veterans;if(!v)return '';const n=v.next,last=v.tiers[v.tiers.length-1].min_cents,pct=Math.min(100,Math.round(v.base_cents/last*100));
 return `<div class="vd-box"><div class="vd-box-head"><span class="vd-eyebrow">Veterans Day · today only</span><strong>${v.unlocked?`You’re at Tier ${v.unlocked} of 4`:'Free gifts with your first box'}</strong></div>
<div class="vd-meter" role="img" aria-label="${money(v.base_cents)} of ${vdUsd(last)}"><i style="width:${pct}%"></i>${v.tiers.map(t=>`<b class="${t.unlocked?'on':''}" style="left:${Math.round(t.min_cents/last*100)}%"></b>`).join('')}</div>
${n?`<p class="vd-next">Add <strong>${money(n.need_cents)}</strong> more to reach <strong>Tier ${v.tiers.findIndex(t=>t.id===n.id)+1}</strong>: ${esc(vdGiftText(v.tiers.find(t=>t.id===n.id),v))}</p>`:'<p class="vd-next"><strong>You unlocked every gift.</strong> Thank you!</p>'}
<ul class="vd-list">${v.tiers.map(t=>`<li class="${t.unlocked?'on':''}"><span class="vd-check" aria-hidden="true">${t.unlocked?'✓':''}</span><span><b>Tier ${v.tiers.indexOf(t)+1}</b> <small class="vd-at">${vdUsd(t.min_cents)}+</small><br>${esc(vdBoxText(t,v))}</span></li>`).join('')}</ul>
${v.tiers.some(t=>t.unlocked&&t.bag)&&(v.totes||[]).length?`<label class="vd-pick">Your free Glow tote<select id="vd-bag"><option value="">Choose your tote</option>${v.totes.map(x=>`<option value="${x.id}"${String(x.id)===String(state.vdBag)?' selected':''}>${esc(x.name)}</option>`).join('')}</select></label>${(()=>{const t=v.totes.find(x=>String(x.id)===String(state.vdBag));return t&&t.image?`<img class="vd-tote-photo" src="${esc(t.image)}" alt="${esc(t.name)}" loading="lazy">`:''})()}`:''}
${v.tiers.some(t=>t.unlocked&&t.kit)?(v.kits.length?`<label class="vd-pick">Your free Kit of 10<select id="vd-kit"><option value="">Choose your kit</option>${v.kits.map(k=>`<option value="${k.id}"${k.id===state.vdKit?' selected':''}>${esc(k.name)} · ${money(k.price_cents)} value</option>`).join('')}</select></label>`:'<p class="notice">Every eligible kit is sold out right now. Message us and we will make it right.</p>'):''}
<p class="vd-fine">Counted on your first box after the 15% off, before shipping. Gifts are added to your first box at no charge. They are not part of the boxes that follow.</p></div>`}
function savedCheckoutNotice(){return state.savedCheckout&&!state.editingOrderId?`<section class="notice" aria-label="Saved checkout"><div class="row"><span><strong>You have a saved checkout.</strong> Already paid? Resume it to upload your screenshot and submit. Do not pay again.</span>${button('Resume checkout','resume-checkout','secondary')}</div></section>`:''}
function adminAvail(p){if(Array.isArray(p.components)&&p.components.length)return Math.min(...p.components.map(c=>{const x=(state.admin&&state.admin.products||[]).find(y=>y.id===c.id);return x?Math.floor(Math.max(0,x.stock)/c.qty):0}));return p.units>1?Math.floor(p.stock/p.units):p.stock}
function productSection(p){if(p.category==='merch'||p.merch_design)return 'merch';if(p.units>1)return 'kits';if(p.category==='cosmetic')return 'beauty';const sku=String(p.sku||'').toLowerCase();if(sku.startsWith('bundle-'))return 'bundles';if(/^(protocol-|glow-eyes|rose-recovery|cu-hair)/.test(sku))return 'beauty';if(/^(bac-water|acetic-acid)/.test(sku))return 'supplies';return 'research'}
