function beautyProductDescription(p){const key=p.slug||Object.keys(BEAUTY_PRODUCT_COPY).sort((a,b)=>b.length-a.length).find(slug=>String(p.sku||'').startsWith(slug+'-'));const copy=BEAUTY_PRODUCT_COPY[key];return copy?'<div class="product-description"><p>'+esc(copy.description)+'</p><button type="button" class="desc-more" data-desc-more aria-expanded="false"><span class="more">Read more</span><span class="less">Show less</span></button><p class="product-ingredients"><strong>Key ingredients:</strong> '+esc(copy.ingredients)+'</p></div>':''}
function productCard(p){return `<article class="card vial-photo-card" data-product-id="${p.id}" data-name="${esc(p.name.toLowerCase())}">${p.image?`<div class="vial-photo-frame"><img class="product-image" src="${esc(p.image)}" alt="${esc(p.name)}" loading="lazy" decoding="async" width="960" height="640"></div>`:""}${p.additional_images?.length?`<details class="product-more-photos"><summary>More photos</summary>${p.additional_images.map(src=>`<img class="product-image" src="${esc(src)}" alt="${esc(p.name)} alternate view" loading="lazy">`).join('')}</details>`:''}${typeof isPepOfWeek==='function'&&isPepOfWeek(p)?'<span class="potw-chip">Pep of the Week</span>':''}${typeof skProductTag==='function'?skProductTag(p):''}<h3>${esc(p.name)}</h3>${p.units>1?`<p class="muted kit-note">${p.units} vials · 5% off buying ${p.units} singly</p>`:''}${beautyProductDescription(p)}${p.max_order_quantity?'<p class="muted">Limit 3 sale vials total per order. Mix and match.</p>':''}${p.promo_excluded?'<p class="muted">Special price · promo codes do not apply</p>':''}<p class="stock">${p.stock?'In stock':'Sold out'}</p>${subCardPrice(p)}<div class="bottom">${productPriceHtml(p)}<button data-action="add" data-id="${p.id}" ${p.stock===0||!productCanAdd(p)?'disabled':''}>${p.stock?'Add to bag':'Out of stock'}</button></div></article>`}
// Subscriber price on every product card (Jonah, 8 Nov 2026): exactly 15% off, only while Subscribe & save is open.
function subCardPrice(p){if(!state.catalog?.settings?.subscribe_open||!p.stock||p.max_order_quantity||Math.ceil((p.price||0)/6500)>8)return '';const reg=Math.max(Number(p.regular_price)||0,p.price),sp=reg>p.price?Math.min(p.price,Math.floor(reg*85/100)):Math.floor(p.price*85/100);if(sp>=p.price)return '';let member=false;try{member=localStorage.getItem('glow_subscriber')==='1'}catch{}if(member)return `<a class="sub-card-price" href="/store-next/account?addon=${p.id}#subscriptions"><span class="sc-label">Add to next package</span><strong>${money(sp)}</strong><span class="sc-go" aria-hidden="true">→</span></a>`;return `<button type="button" class="sub-card-price" data-action="sub-add" data-id="${p.id}" aria-label="Subscribe and save: ${esc(p.name)} for ${money(sp)} per delivery"><span class="sc-label">Subscribe &amp; save</span><strong>${money(sp)}</strong><span class="sc-go" aria-hidden="true">→</span></button>`}
function groupedProducts(){const products=[...state.catalog.products].sort((a,b)=>a.name.localeCompare(b.name,'en',{numeric:true,sensitivity:'base'}));return [['research','Products'],['kits','Kits of 10'],['bundles','Bundles'],['beauty','Beauty & hair care'],['supplies','Supplies']].map(([key,title])=>{const rows=products.filter(p=>productSection(p)===key&&!(key==='kits'&&!(p.stock>0)));return rows.length?`<section class="collection-group" id="collection-${key}" data-product-group><div class="section-heading"><h2>${title}</h2><span class="muted count-pill">${rows.length} options</span></div><div class="grid">${rows.map(p=>productCard(p)).join('')}</div></section>`:''}).join('')}
function collectionShortcuts(){const has=key=>state.catalog.products.some(p=>productSection(p)===key&&!(key==='kits'&&!(p.stock>0)));const links=[['research','Products'],['kits','Kits of 10'],['bundles','Bundles'],['beauty','Beauty & hair'],['supplies','Supplies']].filter(([key])=>has(key)).map(([key,title])=>`<a href="#collection-${key}">${title}</a>`).join('');return `<nav class="collection-shortcuts" aria-label="Browse collections">${links}${BR().id==='glow'?'<a href="/store-next/merch.html">Glow Merch</a>':''}</nav>`}
