 const M0=c=>'$'+Math.round((c||0)/100).toLocaleString('en-US'),today=etDayOf(Date.now()/1000),month=today.slice(0,7),dayN=Number(today.slice(8)),dim=new Date(Date.UTC(Number(month.slice(0,4)),Number(month.slice(5)),0)).getUTCDate();
 const live=d.orders.filter(o=>o.is_test===false&&!isCheckoutDraft(o)),paid=live.filter(o=>['paid','shipped'].includes(o.status)&&!o.legacy_import),val=o=>o.verified_payment_cents??o.total;
 const todayPaid=paid.filter(o=>etDayOf(o.created)===today),mtd=paid.filter(o=>etDayOf(o.created).slice(0,7)===month),mtdSum=mtd.reduce((n,o)=>n+val(o),0),todaySum=todayPaid.reduce((n,o)=>n+val(o),0);
 const prevKey=(()=>{const y=Number(month.slice(0,4)),m=Number(month.slice(5));return m===1?(y-1)+'-12':y+'-'+String(m-1).padStart(2,'0')})(),prevName=new Date(Date.UTC(Number(prevKey.slice(0,4)),Number(prevKey.slice(5))-1,15)).toLocaleDateString('en-US',{month:'long',timeZone:'UTC'});
 const lastMonth=MONTH_HISTORY[prevKey]??paid.filter(o=>etDayOf(o.created).slice(0,7)===prevKey).reduce((n,o)=>n+val(o),0),setGoal=t&&!t.error?t.goal_cents:0,beatLast=lastMonth>0&&lastMonth>=setGoal;
 const goal=t&&!t.error?Math.max(setGoal||0,lastMonth):0,pace=goal?Math.round(goal*dayN/dim):0,proj=dayN?Math.round(mtdSum/dayN*dim):0,gap=mtdSum-pace,pctGoal=goal?Math.min(100,Math.round(mtdSum/goal*100)):0;
 const toPack=live.filter(o=>o.status==='paid'),unpaid=unpaidList().filter(o=>o.status!=='expired'),unpaidSum=unpaid.reduce((n,o)=>n+(o.balance_due_cents||o.total||0),0);
 const low=(d.products||[]).filter(p=>p.active&&Number.isFinite(p.stock)&&p.stock<=5&&!(p.components&&p.components.length)&&!p.stock_pool).sort((a,b)=>a.stock-b.stock).slice(0,8);
 const recent=live.slice().sort((a,b)=>(b.created||0)-(a.created||0)).slice(0,6);
